function renderWinRank(){
  if(!winRankEl)return;
  const labels=['NHẤT','NHÌ','BA','BÉT'],ranked=teams.map((team,i)=>({team,i,wins:Number(winStats[i])||0})).filter(item=>item.wins>0).sort((a,b)=>b.wins-a.wins||a.i-b.i);
  winRankEl.innerHTML=labels.map((label,rank)=>{const item=ranked[rank];return `<div class="win-rank-item rank-${rank+1} ${item?'has-win':''}" style="--team:${item?.team.css||'#6f7d93'}"><div class="rank-cannon"><i></i><span></span></div><div class="rank-podium"><b>${rank+1}</b></div><div class="rank-info"><strong>${label}</strong><em>${item?.team.name||'—'}</em><span>${item?`${item.wins} WIN${item.wins>1?'S':''}`:'0 WIN'}</span></div></div>`}).join('');
}
