function findAliasIndex(text,groups){return groups.findIndex(group=>group.some(alias=>hasAlias(text,alias)))}
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,match=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[match]))}
function userKey(user={}){return String(user.uniqueId||user.userId||user.nickname||'').trim()}
