function testAvatar(team){const color=teams[team].css.replace('#','%23'),label=encodeURIComponent(teams[team].name.slice(0,2));return `data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 120"><rect width="120" height="120" rx="60" fill="${color}"/><circle cx="60" cy="46" r="24" fill="white" fill-opacity=".92"/><path d="M22 110c8-27 27-40 38-40s30 13 38 40" fill="white" fill-opacity=".9"/><text x="60" y="70" text-anchor="middle" font-family="Arial" font-size="24" font-weight="900" fill="${color}">${label}</text></svg>`}
function simulateComment(team){requestLiveCommentSkill(teams[team].name.toLowerCase(),{uniqueId:`comment_${teams[team].name.toLowerCase()}`,nickname:`Viewer ${teams[team].name}`,userId:`comment-${team}`,avatar:testAvatar(team)})}
