function giftTeamFromEvent(data){if(Number.isInteger(data?.teamIndex))return data.teamIndex;if(Number.isInteger(data?.team))return data.team;const teamName=normalizeCommentText(data?.team||'');const byName=findAliasIndex(teamName,TEAM_COMMENT_ALIASES);if(byName>=0)return byName;const key=userKey(data?.user);return key&&liveUserTeams.has(key)?liveUserTeams.get(key):-1}
