function buildSettings(){const host=document.querySelector('#settingsFields');host.innerHTML=Object.entries(SETTINGS_GROUPS).map(([group,fields])=>`<section class="setting-group"><h3>${group}</h3>${fields.map(([key,label,step])=>`<div class="setting-row ${step==='toggle'?'toggle-row':''}"><label for="setting-${key}">${label}</label>${step==='select'?`<select id="setting-${key}" data-key="${key}">${BACKGROUND_THEMES.map(([name],i)=>`<option value="${i}" ${Number(CONFIG[key])===i?'selected':''}>${name}</option>`).join('')}</select>`:`<input id="setting-${key}" data-key="${key}" type="${step==='toggle'?'checkbox':'number'}" ${step==='toggle'?(CONFIG[key]?'checked':''):`step="${step}" value="${CONFIG[key]}"`}>`}</div>`).join('')}</section>`).join('')}
function applyRuntimeSettings(next){
  Object.assign(CONFIG,next||{});
  if(next&&Object.hasOwn(next,'backgroundTheme')){scene.background?.dispose?.();scene.background=skyTexture(CONFIG.backgroundTheme)}
  camera.fov=CONFIG.cameraFov;camera.position.set(0,CONFIG.cameraY,CONFIG.cameraZ);camera.lookAt(0,0,-1.2);camera.updateProjectionMatrix();
  renderer.toneMappingExposure=1.08;
  giftPositions.forEach((pos,i)=>{if(Number.isFinite(Number(CONFIG[`avatar${i}X`])))pos.x=Number(CONFIG[`avatar${i}X`]);if(Number.isFinite(Number(CONFIG[`avatar${i}Y`])))pos.y=Number(CONFIG[`avatar${i}Y`])});
  if(grid?.length)rebuildTiles();
  applyGiftAvatarPositions();
  const maxLines=THREE.MathUtils.clamp(Math.round(Number(CONFIG.commentMaxLines)||6),1,12);if(commentFeedEl)while(commentFeedEl.children.length>maxLines)commentFeedEl.lastElementChild.remove();
  if(avatarEditMode)showAvatarEditPreview();
}
function saveSettings(){const next={...CONFIG};document.querySelectorAll('#settingsFields input,#settingsFields select').forEach(input=>{if(input.type==='checkbox')next[input.dataset.key]=input.checked?1:0;else{const value=Number(input.value);if(Number.isFinite(value))next[input.dataset.key]=value}});localStorage.setItem('colorCannonsSettings',JSON.stringify(next));applyRuntimeSettings(next)}
function restoreSettings(){localStorage.removeItem('colorCannonsSettings');applyRuntimeSettings(DEFAULTS)}
function handleExternalControl(data){
  if(!data||typeof data!=='object')return;
  if(data.__id){if(handledControlMessages.has(data.__id))return;handledControlMessages.add(data.__id);if(handledControlMessages.size>80)handledControlMessages.delete(handledControlMessages.values().next().value)}
  if(data.type==='skill')requestSkill(Number(data.team),String(data.skill),document.querySelector(`.skill-button[data-team="${Number(data.team)}"][data-skill="${String(data.skill)}"]`));
  else if(data.type==='kill')eliminateCannon(cannons[Number(data.team)]);
  else if(data.type==='commentTest')simulateComment(Number(data.team));
  else if(data.type==='giftTest')simulateGift(Number(data.team));
  else if(data.type==='reset')reset();
  else if(data.type==='resetAll')resetAllGame();
  else if(data.type==='reload')location.reload();
  else if(data.type==='settingsUpdate')applyRuntimeSettings(data.settings||{});
  else if(data.type==='avatarEdit')setAvatarEditMode(!!data.enabled);
  else if(data.type==='gifterMock')setGifterMock(!!data.enabled);
  else if(data.type==='exportAvatarPositions')exportAvatarPositions();
  else if(data.type==='resetAvatarPositions')resetAvatarPositions()
}
function bindExternalControl(){if(controlChannel)controlChannel.onmessage=event=>handleExternalControl(event.data);window.addEventListener('storage',event=>{if(event.key!=='colorCannonsControlMessage'||!event.newValue)return;try{handleExternalControl(JSON.parse(event.newValue))}catch{}})}
